/**
 * FIXED: High-reliability wrapper for getAsync that self-rejects if Outlook stalls,
 * preventing the entire add-in background task container from being killed with a 5018 timeout error.
 */
function getRecipientsWithTimeout(recipientField: Office.Recipients): Promise<Office.EmailAddressDetails[]> {
  const apiCall = new Promise<Office.EmailAddressDetails[]>((resolve, reject) => {
    recipientField.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        resolve(result.value || []);
      } else {
        reject(result.error);
      }
    });
  });

  // Self-destruct lookup execution if it stalls longer than 2.5 seconds
  const timeoutFallback = new Promise<Office.EmailAddressDetails[]>((_, reject) =>
    setTimeout(() => reject(new Error("Outlook API field lock timeout")), 2500)
  );

  return Promise.race([apiCall, timeoutFallback]);
}

function getRecipientsAsync(recipientField: Office.Recipients): Promise<Office.EmailAddressDetails[]> {
  return new Promise((resolve, reject) => {
    recipientField.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        resolve(result.value);
      } else {
        reject(result.error);
      }
    });
  });
}

function hasInvalidDomain(recipients: Office.EmailAddressDetails[], _allowedDomain: string): boolean {
  const domain = Office.context.mailbox.userProfile.emailAddress.split("@")[1].toLowerCase();
  return recipients.some((recipient) => {
    const email = recipient.emailAddress ? recipient.emailAddress.toLowerCase().trim() : "";
    return email.length > 0 && !email.endsWith(domain.toLowerCase());
  });
}



// Register functions inside Office Action Management framework
Office.actions.associate("action", action);
Office.actions.associate("onMessageRecipientsChangedHandler", onMessageRecipientsChangedHandler);
Office.actions.associate("onNewMessageComposeHandler", onNewMessageComposeHandler);
Office.actions.associate("OnMessageCompose", onMessageComposeHandler);

// Expose functions explicitly to the Webpack window context for functional background executions
(window as any).action = action;
(window as any).onMessageRecipientsChangedHandler = onMessageRecipientsChangedHandler;
(window as any).onNewMessageComposeHandler = onNewMessageComposeHandler;
